    /* ===================== TWIBBON: HELPER KIRIM ===================== */

    async function kirimTwibbon(frameB64, labelNama) {
        const judul   = document.getElementById('twibbon-judul').value.trim();
        const harga   = parseInt(document.getElementById('twibbon-harga').value) || 0;
        const statusEl = document.getElementById('twibbon-status');

        if (!twibbonImageSrc) { statusEl.innerText = '⚠️ Belum ada foto! Arahkan kursor ke foto lalu Shift+X.'; return; }
        if (!judul)           { statusEl.innerText = '⚠️ Isi nama produk dulu!'; return; }
        if (!harga)           { statusEl.innerText = '⚠️ Isi harga produk dulu!'; return; }

        statusEl.innerText = '🔄 Membuat twibbon ' + labelNama + '...';

        try {
            const blob = await renderTwibbon(frameB64, judul, harga);
            if (!blob) { statusEl.innerText = '❌ Gagal render. Coba Shift+X ulang.'; return; }

             // Refresh canvas preview setelah render
            drawEditorCanvas();

            statusEl.innerText = '📤 Mengirim ke Telegram...';

            const formData = new FormData();
            formData.append('chat_id', CHAT_ID);
            formData.append('photo',   blob, 'twibbon.jpg');
            formData.append('caption', `${judul}\nRp${fmtRupiah(harga)}`);

            const res  = await fetch(`https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendPhoto`, { method: 'POST', body: formData });
            const json = await res.json();

            if (json.ok) {
                statusEl.innerHTML = '✅ Twibbon ' + labelNama + ' berhasil terkirim!';
            } else {
                statusEl.innerText = `❌ Gagal: ${json.description || 'unknown error'}`;
            }
        } catch (err) {
            statusEl.innerText = '❌ Error: ' + err.message;
        }
    }

